select count(wsc1_0.id),coalesce(sum(case when wsc1_0.review_status='CONFIRMED' then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='DISMISSED' then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' and wsc1_0.comparison_status not in ('PENDING','PROCESSING') and not((aj1_0.review_mode='AUTOMATIC' and aj1_0.automatic_applied_at is null and aj1_0.status in ('PENDING','RUNNING'))) then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' and (wsc1_0.comparison_status in ('PENDING','PROCESSING') or (aj1_0.review_mode='AUTOMATIC' and aj1_0.automatic_applied_at is null and aj1_0.status in ('PENDING','RUNNING'))) then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status<>'PENDING_REVIEW' then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' and wsc1_0.comparison_status='PENDING' then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' and wsc1_0.comparison_status='PROCESSING' then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' and wsc1_0.comparison_status='FAILED' then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' and wsc1_0.comparison_status='FAILED' and wsc1_0.comparison_failure_code='AI_TOKEN_QUOTA_EXHAUSTED' then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' and wsc1_0.comparison_status='FAILED' and wsc1_0.comparison_failure_code='AI_TOKEN_QUOTA_EXHAUSTED' and (aj1_0.analysis_mode='ORDERED_PROVISIONAL' or (aj1_0.review_mode='AUTOMATIC' and aj1_0.automatic_applied_at is null and aj1_0.status in ('PENDING','RUNNING'))) then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' and wsc1_0.comparison_status='RECOMPARISON_REQUIRED' then 1 else 0 end),0),coalesce(sum(case when wsc1_0.review_status='PENDING_REVIEW' and wsc1_0.comparison_status='COMPLETED' and wsc1_0.consolidation_status='CONFLICT' then 1 else 0 end),0) from world_setting_candidates wsc1_0 join analysis_jobs aj1_0 on aj1_0.id=wsc1_0.analysis_job_id where wsc1_0.work_id='082683aa-c3d8-56b3-91e2-8031e85f4a92' and aj1_0.batch_id='a87bda2b-9e89-5631-9e1e-852151905d99' and ((NULL is null and aj1_0.source_kind='EPISODE') or aj1_0.id=NULL);
